    \"\"\"A picklable callable for type conversion.\"\"\"
    def __init__(self, func_name, extra_arg=None):
        self.func_name = func_name
        self.extra_arg = extra_arg
        # Map function names to actual functions
        self._funcs = {
            'float': float,
            'int': int,
            'bool': bool,
            'str': str,
        }

    def __call__(self, s, m):
        if isinstance(m, str):
            s = m
        else:
            s = m.group(0)
        func = self._funcs[self.func_name]
        if self.func_name == 'int':
            return int(s, self.extra_arg if self.extra_arg is not None else 10)
        return func(s)


class _TzOffsetFunctor:
    \"\"\"A picklable callable for timezone offset conversion.\"\"\"
    def __init__(self):
        pass

    def __call__(self, s, m):
        tz = m.group(0)
        sign = 1 if tz[0] == '+' else -1
        if ':' in tz:
            tzh, tzm = tz[1:].split(':')
        elif len(tz) == 4:  # 'snnn'
            tzh, tzm = tz[1:3], tz[3:5]
        else:
            tzh, tzm = tz[1:3], tz[3:5]
        return FixedTzOffset(sign * (int(tzh) * 60 + int(tzm)))


class _IntAutoBaseFunctor:
    \"\"\"A picklable callable for integer conversion with auto base detection.\"\"\"
    def __init__(self, base=None):
        self.base = base

    def __call__(self, s, m):
        if isinstance(m, str):
            s = m
        else:
            s = m.group(0)
        # If base is None, use auto-detection based on prefix
        if self.base is None:
            if s.startswith(('0x', '0X', '-0x', '-0X', '+0x', '+0X')):
                return int(s, 16)
            elif s.startswith(('0o', '0O', '-0o', '-0O', '+0o', '+0O')):
                return int(s, 8)
            elif s.startswith(('0b', '0B', '-0b', '-0B', '+0b', '+0B')):
                return int(s, 2)
            else:
                return int(s, 10)
        else:
            return int(s, self.base)


